");
            DefineSection("Scripts", async() => {
                WriteLiteral(@"
    <script>
        document.addEventListener('DOMContentLoaded', function () {
            const track = document.getElementById('services-track');
            const leftBtn = document.getElementById('services-left');
            const rightBtn = document.getElementById('services-right');
            const cardWidth = 380 + 30; // width + gap

            leftBtn.addEventListener('click', () => {
                track.scrollBy({ left: -cardWidth, behavior: 'smooth' });
            });

            rightBtn.addEventListener('click', () => {
                track.scrollBy({ left: cardWidth, behavior: 'smooth' });
            });

            // Автоматическая прокрутка каждые 6 секунд
            let autoScroll = setInterval(() => {
                if (track.scrollLeft + track.clientWidth >= track.scrollWidth) {
                    track.scrollTo({ left: 0, behavior: 'smooth' });
                } else {
                    track.scrollBy({ left: cardWidth, behavior: 'smooth' });
      ");
                WriteLiteral(@"          }
            }, 6000);

            // Остановка автоматической прокрутки при взаимодействии пользователя
            track.addEventListener('mouseenter', () => {
                clearInterval(autoScroll);
            });

            track.addEventListener('mouseleave', () => {
                autoScroll = setInterval(() => {
                    if (track.scrollLeft + track.clientWidth >= track.scrollWidth) {
                        track.scrollTo({ left: 0, behavior: 'smooth' });
                    } else {
                        track.scrollBy({ left: cardWidth, behavior: 'smooth' });
                    }
                }, 6000);
            });
        });
    </script>
");
            }
            );
        }
